; $9e27-$9e8f

; Starts the tune that sound_request,x asks for on voice X. When sound is off, drops requests of $83 and higher.
start_sound_request
        txa
        asl
        tay
        lda sound_request,x
        cmp #$83
        bcc start_sound_request_accept
        lda sound_off
        bpl start_sound_request_accept
; not executed $9e34-$9e38
        lda #$00
        sta sound_request,x
        rts
start_sound_request_accept
        lda sound_request,x
        sta voice_tune,x
        lda #$00                        ; Stops the effects, the note time and the filter sweep. Read offset = 0.
        sta filter_speed
        sta sound_request,x
        sta effect_flags,x
        sta note_time,y
        sta note_time+1,y
        sta voice_data_offset,y
        sta voice_data_offset+1,y
        ldy voice_sid_offsets,x
        lda sid_shadow_control,y
        and #$f6
        sta sid_shadow_control,y
        lda sid_shadow_res_filt         ; Clears the resonance and the filter bit of the voice.
        and #$0f
        and bit_masks_inverted,x
        sta sid_shadow_res_filt
        rts
; Fades the master volume in (to 15) or out (to 0), one step after each fade delay.
update_volume_fade
        lda fade_delay
        bne update_volume_fade_done
        lda fade_in_request
        bpl update_volume_fade_out
        and #$7f
        sta fade_delay
        inc master_volume
        lda master_volume
        cmp #$0f
        bcc update_volume_fade_done
        sta fade_in_request
        jmp update_volume_fade_done
update_volume_fade_out
        lda fade_out_request
        bpl update_volume_fade_done
        and #$7f
        sta fade_delay
        dec master_volume
        bne update_volume_fade_done
        sta fade_out_request
update_volume_fade_done
        rts
